// Zero-based linear axes, derived only from amounts the replay has revealed.
// Prize thresholds are annotations: a distant jackpot must not flatten the race.
export function crapsRaceBankrollScale({ high = 0n, starting = 0n, danger = 0n, wager = 0n } = {}) {
  const peak = [high, starting, danger, wager].reduce((max, value) => {
    const amount = wholeFlip(value) ?? 0n;
    return amount > max ? amount : max;
  }, 1n);
  const required = (peak * 115n + 99n) / 100n;
  const roughStep = (required + 4n) / 5n;
  let magnitude = 1n;
  while (magnitude * 10n <= roughStep) magnitude *= 10n;
  const step = [10n, 20n, 25n, 50n, 100n]
    .map(factor => (magnitude * factor + 9n) / 10n)
    .find(value => value >= roughStep);
  return Object.freeze({ max: step * 5n, ticks: Object.freeze(
    Array.from({ length: 6 }, (_, index) => step * BigInt(index)),
  ) });
}

export function crapsRaceRollAxis(roundNumber = 0, minimum = 20) {
  const round = Number(roundNumber);
  const max = Math.max(minimum, Number.isFinite(round) ? Math.floor(round) : 0);
  const roughStep = max / 5;
  const magnitude = 10 ** Math.floor(Math.log10(roughStep));
  const step = [1, 2, 5, 10].map(factor => factor * magnitude).find(value => value >= roughStep);
  const ticks = [];
  for (let roll = 0; roll <= max; roll += step) ticks.push(roll);
  return Object.freeze({ max, ticks: Object.freeze(ticks) });
}

