export function normalizeCrapsResolutionSpeed(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 1;
  return Math.max(0.5, Math.min(3, Math.round(numeric * 2) / 2));
}

export function crapsResolutionDelay(milliseconds, speed = 1, baseline = 2) {
  const duration = Number(milliseconds);
  if (!Number.isFinite(duration) || duration <= 0) return 0;
  const normalizedSpeed = normalizeCrapsResolutionSpeed(speed);
  // The former 2x pace is now normal. Manual controls roll progression only;
  // its animations use the same baseline as 1x.
  return Math.max(0, Math.round(duration / (baseline * (normalizedSpeed === 0.5 ? 1 : normalizedSpeed))));
}

/** One result swap, one physical impact, then settlement. */
export function crapsRollImpactCadence(speed = 1, baseline = 2) {
  const normalizedSpeed = normalizeCrapsResolutionSpeed(speed);
  const multiplier = normalizedSpeed === 0.5 ? 1 : normalizedSpeed;
  // Explicit legacy timing remains available to callers; both live skins use baseline 2.
  if (baseline === 1) return Object.freeze({
    speed: normalizedSpeed,
    impactMs: Math.max(150, crapsResolutionDelay(280, normalizedSpeed, 1)),
    readoutMs: Math.max(500, crapsResolutionDelay(900, normalizedSpeed, 1)),
    holdMs: Math.max(300, crapsResolutionDelay(420, normalizedSpeed, 1)),
  });
  // These were the actual 2x timings, including the old readability floors.
  // Scale those beats too so 2x/3x remain faster than the new normal.
  return Object.freeze({
    speed: normalizedSpeed,
    impactMs: Math.round(150 / multiplier),
    readoutMs: Math.round(500 / multiplier),
    holdMs: Math.round(300 / multiplier),
  });
}

